import { vectorTypeFor } from "../db/migrations/runner.js";
import { quoteIdentifier, sqlStringLiteral } from "../db/tables.js";
import {
	contentTsvExpression,
	DEFAULT_TEXT_SEARCH_CONFIG,
} from "../db/text-search.js";

/**
 * The first line of every file `generate --adapter drizzle` writes. A file
 * that starts with it is one the command may replace; any other file at the
 * path is the app's and is kept.
 */
export const DRIZZLE_SCHEMA_HEADER =
	"// Generated by mnemocyte generate --adapter drizzle.";

export interface DrizzleSchemaInput {
	/** The embedding size: `vector` up to 2,000, `halfvec` above. */
	readonly dimensions: number;
	/** `content_tsv`'s configuration. @defaultValue `"english"` */
	readonly textSearchConfig?: string;
	/** The Postgres schema of the tables, or null for `search_path`. */
	readonly schema?: string | null;
	/** The package version, recorded in the header. */
	readonly version: string;
}

/** The SQL drizzle-kit cannot write, as custom migrations around its own. */
export interface DrizzleSetupSql {
	/** Before the tables: pgvector, whose types the tables use. */
	readonly before: string;
	/** After the tables: the key index and the installation row. */
	readonly after: string;
}

// The indexes, constraints and generated expressions below are those of
// migrations/0000_initial.sql.template. test/contract/drizzle-schema.test.ts
// runs this file through drizzle-kit and compares the catalog with a fresh
// install, so the two cannot drift.

/** `memory_id` of `0004_audit_memory_id.sql`, as in the template. */
const EVENT_MEMORY_ID_EXPRESSION = `CASE WHEN "metadata"->>'memoryId' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN ("metadata"->>'memoryId')::uuid END`;

/**
 * `text` inside a JavaScript template literal: drizzle's `sql` tag reads the
 * cooked strings, so a backslash, a backtick and `${` are escaped and come
 * out as written.
 */
function templateText(text: string): string {
	return text
		.replaceAll("\\", "\\\\")
		.replaceAll("`", "\\`")
		.replaceAll("${", "\\${");
}

function sqlTag(text: string): string {
	return `sql\`${templateText(text)}\``;
}

/**
 * `content_tsv`'s generated expression as the schema file writes it, so a
 * caller can tell whether a file already has `textSearchConfig`.
 */
export function drizzleContentTsvSource(textSearchConfig: string): string {
	return sqlTag(contentTsvExpression(textSearchConfig));
}

/**
 * An `import` of `names` from `from`, one name per line past one. Built
 * here rather than written into the template, so no line of the bundled
 * bin starts with an import of drizzle-orm (a package test checks that the
 * bin imports no driver).
 */
function importStatement(names: readonly string[], from: string): string {
	const list =
		names.length === 1
			? `{ ${names[0]} }`
			: `{\n${names.map((name) => `\t${name},`).join("\n")}\n}`;
	return `import ${list} from ${JSON.stringify(from)};`;
}

/**
 * The Mnemocyte tables as a Drizzle schema module (drizzle-orm 0.45), for an
 * app whose migrations drizzle-kit owns. It is text: nothing here imports
 * drizzle-orm. Three parts of the schema are left to
 * {@link renderDrizzleSetupSql}, because drizzle-kit cannot write them:
 * the pgvector extension, the `NULLS NOT DISTINCT` unique index (drizzle-orm
 * has `nullsNotDistinct` only on unique constraints, which cannot be
 * partial) and the `installation` row.
 */
export function renderDrizzleSchema(input: DrizzleSchemaInput): string {
	const { dimensions, version } = input;
	const textSearchConfig = input.textSearchConfig ?? DEFAULT_TEXT_SEARCH_CONFIG;
	const schema = input.schema ?? null;
	const vectorType = vectorTypeFor(dimensions);
	const table = schema === null ? "pgTable" : "mnemocyteSchema.table";
	const imports = [
		"check",
		"customType",
		"foreignKey",
		vectorType,
		"index",
		"integer",
		"jsonb",
		...(schema === null ? ["pgTable"] : ["pgSchema"]),
		"real",
		"text",
		"timestamp",
		"uuid",
	].sort();
	const where = schema === null ? "search_path (usually public)" : schema;

	return `${DRIZZLE_SCHEMA_HEADER}
// mnemocyte ${version}, ${dimensions} dimensions, text search configuration
// ${JSON.stringify(textSearchConfig)}, tables in ${where}. Run the command again rather than
// editing this file.
//
// drizzle-kit cannot write three parts of the schema; the command prints
// them as SQL for custom migrations (drizzle-kit generate --custom):
// - CREATE EXTENSION vector, before these tables;
// - the unique index mnemocyte_memories_scope_key_idx, which needs
//   NULLS NOT DISTINCT;
// - the "installation" row of mnemocyte_meta.
// drizzle-kit push would drop that index: use generate and migrate.
// https://github.com/Meenic/mnemocyte/blob/main/docs/guide/postgres.md#manage-the-tables-with-drizzle-kit
${importStatement(["sql"], "drizzle-orm")}
${importStatement(imports, "drizzle-orm/pg-core")}

const tsvector = customType<{ data: string }>({
	dataType() {
		return "tsvector";
	},
});
${
	schema === null
		? ""
		: `
export const mnemocyteSchema = pgSchema(${JSON.stringify(schema)});
`
}
export const mnemocyteEvents = ${table}(
	"mnemocyte_events",
	{
		id: uuid("id").primaryKey(),
		entityId: text("entity_id").notNull(),
		description: text("description").notNull(),
		metadata: jsonb("metadata")
			.$type<Record<string, unknown>>()
			.default(sql\`'{}'::jsonb\`)
			.notNull(),
		timestamp: timestamp("timestamp", { withTimezone: true })
			.defaultNow()
			.notNull(),
		namespace: text("namespace").notNull(),
		agentId: text("agent_id"),
		sessionId: text("session_id"),
		memoryId: uuid("memory_id").generatedAlwaysAs(
			${sqlTag(EVENT_MEMORY_ID_EXPRESSION)},
		),
	},
	(table) => [
		index("mnemocyte_events_scope_time_idx").using(
			"btree",
			table.namespace,
			table.entityId,
			table.timestamp,
			table.id,
		),
		index("mnemocyte_events_memory_idx").using(
			"btree",
			table.memoryId,
			table.timestamp,
			table.id,
		),
	],
);

export const mnemocyteMeta = ${table}(
	"mnemocyte_meta",
	{
		key: text("key").primaryKey(),
		embeddingDimensions: integer("embedding_dimensions").notNull(),
		embeddingModel: text("embedding_model"),
		vectorType: text("vector_type").default("vector").notNull(),
	},
	(table) => [
		check(
			"mnemocyte_meta_vector_type_check",
			sql\`"vector_type" IN ('vector', 'halfvec')\`,
		),
	],
);

export const mnemocyteMemories = ${table}(
	"mnemocyte_memories",
	{
		id: uuid("id").primaryKey(),
		entityId: text("entity_id").notNull(),
		content: text("content").notNull(),
		kind: text("kind").default("fact").notNull(),
		importance: text("importance").default("normal").notNull(),
		tags: text("tags").array().default([]).notNull(),
		source: text("source"),
		metadata: jsonb("metadata")
			.$type<Record<string, unknown>>()
			.default(sql\`'{}'::jsonb\`)
			.notNull(),
		confidence: real("confidence").default(1).notNull(),
		embedding: ${vectorType}("embedding", { dimensions: ${dimensions} }),
		embeddingModel: text("embedding_model").notNull(),
		embeddingDimensions: integer("embedding_dimensions").notNull(),
		supersededBy: uuid("superseded_by"),
		supersededAt: timestamp("superseded_at", { withTimezone: true }),
		expiresAt: timestamp("expires_at", { withTimezone: true }),
		lastAccessedAt: timestamp("last_accessed_at", { withTimezone: true }),
		accessCount: integer("access_count").default(0).notNull(),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		updatedAt: timestamp("updated_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		namespace: text("namespace").notNull(),
		agentId: text("agent_id"),
		sessionId: text("session_id"),
		key: text("key"),
		contentTsv: tsvector("content_tsv").generatedAlwaysAs(
			${drizzleContentTsvSource(textSearchConfig)},
		),
	},
	(table) => [
		foreignKey({
			name: "mnemocyte_memories_superseded_by_mnemocyte_memories_id_fk",
			columns: [table.supersededBy],
			foreignColumns: [table.id],
		}),
		index("mnemocyte_memories_scope_idx").using(
			"btree",
			table.namespace,
			table.entityId,
			table.agentId,
			table.sessionId,
		),
		// mnemocyte_memories_scope_key_idx is in the custom migration.
		index("mnemocyte_memories_superseded_by_idx")
			.using("btree", table.supersededBy)
			.where(sql\`"superseded_by" IS NOT NULL\`),
		index("mnemocyte_memories_content_tsv_idx").using(
			"gin",
			table.contentTsv,
		),
		index("mnemocyte_memories_embedding_hnsw_idx").using(
			"hnsw",
			table.embedding.op("${vectorType}_cosine_ops"),
		),
	],
);
`;
}

/**
 * The SQL for the two custom migrations next to drizzle-kit's own: pgvector
 * before the tables, then the key index and the `installation` row, as
 * `0000_initial.sql.template` writes them. Names are qualified with
 * `schema` when there is one, since a custom migration runs with the
 * connection's `search_path`.
 */
export function renderDrizzleSetupSql(input: {
	readonly dimensions: number;
	readonly schema?: string | null;
}): DrizzleSetupSql {
	const schema = input.schema ?? null;
	const prefix = schema === null ? "" : `${quoteIdentifier(schema)}.`;
	const vectorType = vectorTypeFor(input.dimensions);
	return {
		before: "CREATE EXTENSION IF NOT EXISTS vector;\n",
		after: `CREATE UNIQUE INDEX "mnemocyte_memories_scope_key_idx" ON ${prefix}"mnemocyte_memories" USING btree ("namespace","entity_id","agent_id","session_id","key") NULLS NOT DISTINCT WHERE "key" IS NOT NULL;
--> statement-breakpoint
INSERT INTO ${prefix}"mnemocyte_meta" ("key", "embedding_dimensions", "vector_type") VALUES ('installation', ${input.dimensions}, ${sqlStringLiteral(vectorType)});
`,
	};
}

/**
 * What to add to the migration drizzle-kit writes for a new text search
 * configuration. drizzle-kit drops `content_tsv` and adds it back, which
 * drops its GIN index, and its snapshot still lists the index, so it never
 * creates it again. `ANALYZE` gives the planner statistics for the new
 * column, as `setTextSearchConfig` does.
 */
export function renderDrizzleTextSearchIndexSql(input: {
	readonly schema?: string | null;
}): string {
	const schema = input.schema ?? null;
	const table = `${schema === null ? "" : `${quoteIdentifier(schema)}.`}"mnemocyte_memories"`;
	return `--> statement-breakpoint
CREATE INDEX "mnemocyte_memories_content_tsv_idx" ON ${table} USING gin ("content_tsv");
--> statement-breakpoint
ANALYZE ${table} ("content_tsv");
`;
}

/** What a schema file was made for, read back from its source. */
export interface DrizzleSchemaShape {
	readonly dimensions: number;
	readonly schema: string | null;
}

const EMBEDDING_SOURCE =
	/^\t\tembedding: (?:vector|halfvec)\("embedding", \{ dimensions: (\d+) \}\),$/m;
const SCHEMA_SOURCE =
	/^export const mnemocyteSchema = pgSchema\(("[^"\n]*")\);$/m;

/**
 * The dimensions and schema of a file {@link renderDrizzleSchema} wrote, or
 * null when its source no longer has the lines it wrote.
 */
export function readDrizzleSchemaShape(
	source: string,
): DrizzleSchemaShape | null {
	const dimensions = EMBEDDING_SOURCE.exec(source)?.[1];
	if (dimensions === undefined) {
		return null;
	}
	const schema = SCHEMA_SOURCE.exec(source)?.[1];
	return {
		dimensions: Number(dimensions),
		schema: schema === undefined ? null : (JSON.parse(schema) as string),
	};
}
